/**
 * Apply import rules to already-parsed rows.
 * `amount` must be a safe integer number of cents.
 * `today` must be a YYYY-MM-DD calendar date.
 *
 * Counts describe this batch; detecting duplicates against persisted
 * transactions requires the caller to supply that existing state separately.
 */
export function importRows(rows, today) {
	function isValidDate(value) {
		if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
			return false;
		}
		const date = new Date(`${value}T00:00:00Z`);
		return Number.isFinite(date.getTime()) &&
			date.toISOString().slice(0, 10) === value;
	}

	if (!Array.isArray(rows)) {
		throw new Error("ledger: import rows must be an array");
	}
	if (!isValidDate(today)) {
		throw new Error("ledger: invalid today date; expected YYYY-MM-DD");
	}

	const rowsToImport = [];
	const seen = new Set();
	const warnings = [];
	let skipped = 0;
	let deduplicated = 0;

	for (const [index, row] of rows.entries()) {
		const label = `ledger: import row ${index + 1}`;

		if (!row || typeof row !== "object" || Array.isArray(row)) {
			throw new Error(`${label}: expected a transaction`);
		}
		if (!isValidDate(row.date)) {
			throw new Error(`${label}: invalid date; expected YYYY-MM-DD`);
		}
		if (typeof row.payee !== "string") {
			throw new Error(`${label}: payee must be a string`);
		}
		if (!Number.isSafeInteger(row.amount)) {
			throw new Error(`${label}: amount must be safe integer cents`);
		}
		if (row.memo != null && typeof row.memo !== "string") {
			throw new Error(`${label}: memo must be a string`);
		}

		if (row.date > today) {
			skipped++;
			warnings.push(`${label}: future-dated transaction (${row.date}) skipped`);
			continue;
		}

		const key = JSON.stringify([row.date, row.amount, row.payee]);
		if (seen.has(key)) {
			deduplicated++;
			continue;
		}
		seen.add(key);

		rowsToImport.push({
			...row,
			memo: row.memo == null || row.memo.trim() === "" ? row.payee : row.memo,
		});
	}

	return {
		rows: rowsToImport,
		imported: rowsToImport.length,
		skipped,
		deduplicated,
		warnings,
	};
}
